const endpointUrl = "opc.tcp://192.168.0.21:56000";
const DAYS_BACK = 30;
const PAGE = 0;
const PAGE_SIZE = 100;

const now = new Date();
const from = new Date(now.getTime() - (DAYS_BACK * 24 * 60 * 60 * 1000));

node.status({fill:"blue", shape:"dot", text:"connecting..."});

const client = opcua.OPCUAClient.create({
    endpointMustExist: false,
    securityMode: opcua.MessageSecurityMode.None,
    securityPolicy: opcua.SecurityPolicy.None
});

async function run() {
    try {
        await client.connect(endpointUrl);
        const session = await client.createSession();
        node.status({fill:"blue", shape:"dot", text:"calling method..."});

        const methodToCall = {
            objectId: opcua.resolveNodeId("ns=2;s=History"),
            methodId: opcua.resolveNodeId("ns=2;s=History.GetRunHistory"),
            inputArguments: [
                { dataType: opcua.DataType.DateTime, value: from },
                { dataType: opcua.DataType.DateTime, value: now },
                { dataType: opcua.DataType.Int32, value: PAGE },
                { dataType: opcua.DataType.Int32, value: PAGE_SIZE }
            ]
        };

        const result = await session.call(methodToCall);

        let output = {
            statusCode: result.statusCode.toString(),
            outputArguments: []
        };

        if (result.outputArguments) {
            for (let i = 0; i < result.outputArguments.length; i++) {
                let arg = result.outputArguments[i];
                let val = arg.value;
                // Try to parse JSON strings
                if (typeof val === 'string') {
                    try { val = JSON.parse(val); } catch(e) {}
                }
                output.outputArguments.push({
                    dataType: arg.dataType,
                    value: val
                });
            }
        }

        msg.payload = output;
        node.status({fill:"green", shape:"dot", text:"done"});

        await session.close();
        await client.disconnect();

        node.send(msg);
    } catch(err) {
        node.error("OPC UA error: " + err.message, msg);
        node.status({fill:"red", shape:"ring", text: err.message.substring(0,40)});
        try { await client.disconnect(); } catch(e) {}
    }
}

run();
return null; // async, we use node.send()

